{{DropsLineSkill|name=Uncut emerald|quantity=1|rarity=600/3000|skill=Thieving}}
{{DropsLineSkill|name=Emerald|quantity=1|rarity=300/3000|skill=Thieving}}
{{DropsLineSkill|name=Uncut ruby|quantity=1|rarity=300/3000|skill=Thieving}}
