			{ tag = 'argd', content = 'slayerlevel', colspan = '3' }
		}	
	end

	ret:addRow{
		{ tag = 'th', content = '[[Spellbook]]', colspan = '2' },
		{ tag = 'argd', content = 'spellbook', colspan = '3' }
	}

	ret:addRow{
