		{ tag = 'argd', content = 'type', colspan = '3' }
	}

	ret:addRow{
		{ tag = 'th', content = '[[Experience]]', colspan = '2' },
		{ tag = 'argd', content = 'exp', colspan = '3' }
	}

	if ret:paramDefined('element') then
		ret:addRow{
